#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/ElectricBolt/Plan.md (v2: code + shader only, no texture)
    // Blue-white toon electric bolt from the hand (A = prefab origin) to a target 8 m ahead (B = +Z), one shot ~0.45 s.
    // Shaders: VFX/FX/Electric Bolt (bolt body + small arcs, procedural), VFX/FX/Glow Star (glows, flash, star), VFX/FX/Spark (reused).
    public static class ElectricBoltBuild
    {
        const string Effect = "ElectricBolt";
        const string Root = "Assets/VFX/" + Effect;
        const string BoltShader = "VFX/FX/Electric Bolt", GlowShader = "VFX/FX/Glow Star", SparkShader = "VFX/FX/Spark";
        const float Length = 8f;        // A -> B
        const float BoltWidth = 1.6f;   // quad width; the zigzag uses about half of it
        static readonly Vector3 B = new Vector3(0f, 0f, Length);

        static readonly Color Core = new Color(1.4f, 1.5f, 1.6f, 1f);    // HDR white
        static readonly Color Rim = new Color(0.25f, 0.6f, 2.0f, 1f);    // HDR electric blue
        static readonly Color Rim2 = new Color(0.15f, 0.4f, 2.2f, 1f);   // deeper blue for the second bolt
        static readonly Color Cyan = new Color(0.55f, 0.85f, 1f, 1f);    // particle tints

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");

            // 1. Materials (no textures at all)
            var mBolt = BoltMat("Bolt", Rim, aspect: Length / BoltWidth, segments: 8, amp: 0.26f, detail: 0.35f, pin: 12,
                core: 0.025f, rim: 0.07f, strand: 0.6f, glow: 0.25f, fps: 12);
            var mBolt2 = BoltMat("Bolt2", Rim2, aspect: Length / BoltWidth, segments: 10, amp: 0.3f, detail: 0.45f, pin: 10,
                core: 0.012f, rim: 0.04f, strand: 0f, glow: 0.1f, fps: 15);
            var mSide = BoltMat("SideArcs", Rim, aspect: 2f, segments: 4, amp: 0.3f, detail: 0.6f, pin: 8,
                core: 0.03f, rim: 0.08f, strand: 0f, glow: 0.15f, fps: 20);
            var mCurls = BoltMat("ImpactArcs", Rim, aspect: 1f, segments: 3, amp: 0.36f, detail: 0.5f, pin: 6,
                core: 0.025f, rim: 0.065f, strand: 0.4f, glow: 0.15f, fps: 20);
            var mHand = GlowMat("HandGlow", star: false, coreR: 0.14f, rimR: 0.26f, glow: 0.7f);
            var mFlash = GlowMat("ImpactFlash", star: false, coreR: 0.2f, rimR: 0.34f, glow: 0.9f);
            var mStar = GlowMat("ImpactStar", star: true, coreR: 0.06f, rimR: 0.12f, glow: 0.2f);
            var mSpark = Material(Root + "/Materials/M_ElectricBolt_Sparks.mat", VfxBlend.Additive, null, SparkShader);
            mSpark.SetColor("_ColorHead", Core); mSpark.SetColor("_ColorTail", Rim);
            mSpark.SetFloat("_Taper", 0.85f); mSpark.SetFloat("_Soft", 0.15f); mSpark.SetFloat("_Shrink", 0.7f);
            mSpark.SetFloat("_UseParticle", 1f); mSpark.EnableKeyword("_USE_PARTICLE_DATA");
            EditorUtility.SetDirty(mSpark);

            // 2. L1 HandGlow = prefab root: small glow at the hand while the bolt leaves (not an Impact flash)
            var root = new GameObject("VFX_" + Effect);
            var hand = ParticleOn(root, mHand, lifetime: 0.14f, size: 0.8f, color: Color.white);
            SizeOverLifetime(hand, 0f, 0.6f, 0.3f, 1.1f, 1f, 0.8f);
            ColorOverLifetime(hand, new[] { Color.white, Cyan }, 0f, 1f, 0.5f, 0.8f, 1f, 0f);
            Order(hand, 6);

            // 3. L2 Bolt + L2b Bolt2: the bolt body A -> B (Stretched Billboard, length = 5 x width = 8 m).
            //    The particle sits at A and drifts very slowly BACKWARDS (-Z): the stretched quad trails behind it toward B
            //    (same convention as VioletThunder). The shader sweeps the bolt out from A (Custom1.z reach), re-rolls its shape
            //    12-15 times a second, then thins it and breaks it into pieces (Custom1.x).
            Bolt(root, "Bolt", mBolt, 0f, 0.32f, 4);
            var bolt2 = Bolt(root, "Bolt2", mBolt2, 0.1f, 0.24f, 3);
            var b2 = bolt2.main; b2.startColor = new Color(0.8f, 0.8f, 0.8f, 1f);

            // 4. L3 SideArcs: short procedural arcs crackling along the body, random direction
            var side = Particle(root.transform, "SideArcs", mSide, lifetime: 0.1f, size: 0.5f, color: Color.white);
            var sm = side.main;
            sm.startDelay = 0.03f; sm.duration = 0.3f;
            sm.startLifetime = new ParticleSystem.MinMaxCurve(0.06f, 0.12f);
            sm.startSize = new ParticleSystem.MinMaxCurve(0.4f, 0.6f);
            sm.startSpeed = 0.05f; sm.maxParticles = 20;
            var se = side.emission; se.SetBursts(new ParticleSystem.Burst[0]); se.rateOverTime = 40f;
            var ss = side.shape; ss.enabled = true; ss.shapeType = ParticleSystemShapeType.Box;
            ss.position = new Vector3(0f, 0f, Length * 0.5f); ss.scale = new Vector3(0.25f, 0.25f, Length - 0.5f);
            ss.randomDirectionAmount = 1f;
            BoltData(side, reachTime: 0.3f);
            VfxLightningKit.Stretch(side, 2f, 0f, Vector3.zero, 5f, 1);

            // 5. L4 ImpactFlash: the one Impact flash, at B
            var flash = Particle(root.transform, "ImpactFlash", mFlash, lifetime: 0.14f, size: 1.6f, color: Color.white);
            flash.transform.localPosition = B;
            Delay(flash, 0.04f);
            SizeOverLifetime(flash, 0f, 0.6f, 0.3f, 1.15f, 1f, 1.25f);
            ColorOverLifetime(flash, new[] { Color.white, Cyan }, 0f, 1f, 0.4f, 0.9f, 1f, 0f);
            Order(flash, 7);

            // 6. L5 ImpactStar: toon spiky star at B, very short
            var star = Particle(root.transform, "ImpactStar", mStar, lifetime: 0.09f, size: 1.4f, color: Color.white);
            star.transform.localPosition = B;
            Delay(star, 0.05f);
            var stm = star.main; stm.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            SizeOverLifetime(star, 0f, 1f, 1f, 0.7f);
            ColorOverLifetime(star, new[] { Color.white, Cyan }, 0f, 1f, 0.6f, 1f, 1f, 0f);
            Order(star, 8);

            // 7. L6 ImpactArcs: procedural squiggles crackling around B (billboard, random rotation)
            var curls = Particle(root.transform, "ImpactArcs", mCurls, lifetime: 0.15f, size: 0.8f, color: Color.white);
            curls.transform.localPosition = B;
            var cm = curls.main;
            cm.startDelay = 0.05f; cm.duration = 0.3f;
            cm.startLifetime = new ParticleSystem.MinMaxCurve(0.1f, 0.2f);
            cm.startSize = new ParticleSystem.MinMaxCurve(0.6f, 1.0f);
            cm.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            cm.maxParticles = 10;
            var ce = curls.emission; ce.SetBursts(new[] { new ParticleSystem.Burst(0f, 2) }); ce.rateOverTime = 14f;
            var cs = curls.shape; cs.enabled = true; cs.shapeType = ParticleSystemShapeType.Sphere; cs.radius = 0.3f;
            BoltData(curls, reachTime: 0.25f);
            Order(curls, 2);

            // 8. L7 Sparks: streaks thrown off at B, light gravity (VFX/FX/Spark, progress = Custom1.x)
            var sparks = Particle(root.transform, "Sparks", mSpark, lifetime: 0.25f, size: 0.16f, color: Color.white);
            sparks.transform.localPosition = B;
            Delay(sparks, 0.04f);
            var pm = sparks.main;
            pm.startLifetime = new ParticleSystem.MinMaxCurve(0.15f, 0.3f);
            pm.startSpeed = new ParticleSystem.MinMaxCurve(4f, 8f);
            pm.startSize = new ParticleSystem.MinMaxCurve(0.12f, 0.2f);
            pm.gravityModifier = 1f;
            Burst(sparks, 12);
            var ps = sparks.shape; ps.enabled = true; ps.shapeType = ParticleSystemShapeType.Sphere; ps.radius = 0.1f;
            var scd = sparks.customData; scd.enabled = true;
            scd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            scd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 1);
            scd.SetVector(ParticleSystemCustomData.Custom1, 0, new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 0f, 1f, 1f)));
            sparks.GetComponent<ParticleSystemRenderer>().SetActiveVertexStreams(new List<ParticleSystemVertexStream>
            {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Color, ParticleSystemVertexStream.UV, ParticleSystemVertexStream.Custom1X
            });
            VfxLightningKit.Stretch(sparks, 1f, 0.04f, new Vector3(0f, 1f, 0f), 5f, 5);

            // 9. Save, validate, preview (3/4 camera 40 deg down, from the side so the bolt reads full length), demo scene
            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            var target = new Vector3(0f, 0f, Length * 0.5f);
            const float d = 11f, a = 40f * Mathf.Deg2Rad;
            var cam = target + new Vector3(-Mathf.Cos(a) * d, Mathf.Sin(a) * d, 0f);
            Finish(prefab, Root, Effect, new[] { 0.02f, 0.05f, 0.09f, 0.13f, 0.18f, 0.25f, 0.33f, 0.42f }, cam, target);
        }

        public static void BuildBatch() => RunBatch(Build);

        // ---------------------------------------------------------------- local helpers

        static ParticleSystem Bolt(GameObject root, string name, Material mat, float delay, float life, int order)
        {
            var ps = Particle(root.transform, name, mat, lifetime: life, size: BoltWidth, color: Color.white);
            Delay(ps, delay);
            var m = ps.main;
            m.startSpeed = 0.01f;
            m.startRotation = 0f;                            // never random on a bolt
            var s = ps.shape; s.enabled = true;
            s.shapeType = ParticleSystemShapeType.Cone; s.angle = 0f; s.radius = 0.0001f;
            s.rotation = new Vector3(0f, 180f, 0f);          // cone +Z -> -Z: quad trails toward +Z (B)
            BoltData(ps, reachTime: 0.05f / life);
            // stretched along the (tiny) velocity, speed scale 0 -> default pivot kept
            VfxLightningKit.Stretch(ps, Length / BoltWidth, 0f, Vector3.zero, 5f, order);
            return ps;
        }

        /// <summary>Electric Bolt shader data: Custom1.x thin (holds, then thins and breaks), .y seed, .z reach (0 -> 1 by reachTime).</summary>
        static void BoltData(ParticleSystem ps, float reachTime)
        {
            var cd = ps.customData; cd.enabled = true;
            cd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            cd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 3);
            cd.SetVector(ParticleSystemCustomData.Custom1, 0, new ParticleSystem.MinMaxCurve(1f, new AnimationCurve(
                new Keyframe(0f, 0f), new Keyframe(0.55f, 0.05f), new Keyframe(0.85f, 0.55f), new Keyframe(1f, 1f))));
            cd.SetVector(ParticleSystemCustomData.Custom1, 1, new ParticleSystem.MinMaxCurve(0f, 1f));   // seed
            cd.SetVector(ParticleSystemCustomData.Custom1, 2, new ParticleSystem.MinMaxCurve(1f,
                new AnimationCurve(new Keyframe(0f, 0f, 0f, 1f / reachTime), new Keyframe(reachTime, 1f, 1f / reachTime, 0f), new Keyframe(1f, 1f))));
            ps.GetComponent<ParticleSystemRenderer>().SetActiveVertexStreams(new List<ParticleSystemVertexStream>
            {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Color, ParticleSystemVertexStream.UV, ParticleSystemVertexStream.Custom1XYZ
            });
        }

        static Material BoltMat(string layer, Color rimColor, float aspect, float segments, float amp, float detail, float pin,
            float core, float rim, float strand, float glow, float fps)
        {
            var m = Material(Root + "/Materials/M_ElectricBolt_" + layer + ".mat", VfxBlend.Additive, null, BoltShader);
            m.SetFloat("_SrcBlend", 1f); m.SetFloat("_DstBlend", 1f);   // One One: colour is premultiplied in the shader
            m.SetColor("_ColorCore", Core); m.SetColor("_ColorRim", rimColor);
            m.SetFloat("_Aspect", aspect); m.SetFloat("_Segments", segments); m.SetFloat("_Amp", amp);
            m.SetFloat("_Detail", detail); m.SetFloat("_Pin", pin);
            m.SetFloat("_CoreWidth", core); m.SetFloat("_RimWidth", rim);
            m.SetFloat("_Strand", strand); m.SetFloat("_Glow", glow); m.SetFloat("_Fps", fps);
            m.SetFloat("_Flip", 0f);
            m.SetFloat("_UseParticle", 1f); m.EnableKeyword("_USE_PARTICLE_DATA");
            EditorUtility.SetDirty(m);
            return m;
        }

        static Material GlowMat(string layer, bool star, float coreR, float rimR, float glow)
        {
            var m = Material(Root + "/Materials/M_ElectricBolt_" + layer + ".mat", VfxBlend.Additive, null, GlowShader);
            m.SetFloat("_SrcBlend", 1f); m.SetFloat("_DstBlend", 1f);
            m.SetColor("_ColorCore", Core); m.SetColor("_ColorRim", Rim);
            m.SetFloat("_CoreRadius", coreR); m.SetFloat("_RimRadius", rimR); m.SetFloat("_Glow", glow);
            m.SetFloat("_Star", star ? 1f : 0f);
            if (star) { m.EnableKeyword("_STAR"); m.SetFloat("_SpikeSharp", 20f); m.SetFloat("_Diagonal", 0.45f); }
            else m.DisableKeyword("_STAR");
            EditorUtility.SetDirty(m);
            return m;
        }

        static void Delay(ParticleSystem ps, float t)
        {
            var m = ps.main;
            m.startDelay = t;
            m.duration = Mathf.Max(m.duration, 0.1f);
        }

        static void Order(ParticleSystem ps, int order)
        {
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.sortingOrder = order;
            r.maxParticleSize = 5f;
        }
    }
}
#endif
